"""IngeTrazo Stair maker V.1 — parametric stairs for IngeTrazo 0.5.7.

Install this file in the user plugins folder; restart IngeTrazo.
All UI lengths are millimetres; the geometry API uses metres.
"""
from __future__ import annotations

